<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='save'){$name=trim((string)($_POST['name']??''));if($name===''){flash('error','Nama kategori wajib diisi.');redirect('categories');}try{if($id)$pdo->prepare('UPDATE categories SET name=?,slug=? WHERE id=?')->execute([$name,slugify($name),$id]);else $pdo->prepare("INSERT INTO categories(name,slug,icon) VALUES(?,?,'')")->execute([$name,slugify($name)]);flash('success',$id?'Kategori diperbarui.':'Kategori ditambahkan.');}catch(PDOException $e){flash('error','Nama kategori sudah digunakan.');}}elseif($action==='delete'){$stmt=$pdo->prepare('SELECT COUNT(*) FROM twibbons WHERE category_id=?');$stmt->execute([$id]);$used=(int)$stmt->fetchColumn();if($used)flash('error','Kategori tidak dapat dihapus karena digunakan oleh '.$used.' karya.');else{$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);flash('success','Kategori dihapus.');}}redirect('categories');}
$items=$pdo->query('SELECT c.*,COUNT(t.id) total FROM categories c LEFT JOIN twibbons t ON t.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();$flash=pull_flash();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kategori — Semarakin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container"><div class="page-head"><span class="eyebrow">Administrator</span><h1 class="page-title">Kategori karya</h1><p class="subtitle">Kelola kategori agar karya mudah ditemukan.</p></div><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?><section class="panel category-create-inline"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><div class="field"><label>Kategori baru</label><input name="name" required maxlength="80" placeholder="Contoh: Lingkungan"></div><button class="btn btn-primary">Tambahkan</button></form></section><div class="section-head category-list-head"><div><h2>Daftar kategori</h2><p><?=count($items)?> kategori tersedia</p></div></div><div class="responsive-table"><table class="category-table"><thead><tr><th>Kategori</th><th>Slug</th><th>Digunakan</th><th>Ubah nama</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td data-label="Kategori"><strong><?=e($item['name'])?></strong></td><td data-label="Slug"><code><?=e($item['slug'])?></code></td><td data-label="Digunakan"><?=(int)$item['total']?> karya</td><td data-label="Ubah nama"><form method="post" class="table-edit-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><input name="name" value="<?=e($item['name'])?>" required maxlength="80"><button class="btn btn-secondary btn-sm">Simpan</button></form></td><td data-label="Aksi"><?php if((int)$item['total']===0):?><form method="post" data-confirm="Hapus kategori ini?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="btn btn-danger btn-sm">Hapus</button></form><?php else:?><span class="locked-label">Sedang digunakan</span><?php endif?></td></tr><?php endforeach?></tbody></table></div></main><footer class="footer">Semarakin · Apins Digital</footer></body></html>
